<?php require 'includes/auth.php';require_login();require 'config/database.php';$pdo=db();$logs=$pdo->query('SELECT * FROM usage_logs ORDER BY usage_date DESC LIMIT 20')->fetchAll(PDO::FETCH_ASSOC);$types=$pdo->query('SELECT service_type,COUNT(*) c FROM services GROUP BY service_type')->fetchAll(PDO::FETCH_ASSOC);include 'includes/header.php';include 'includes/sidebar.php';?><main><header class="dash-head"><div><p class="tag">INSIGHTS</p><h1>Cloud Analytics</h1></div></header><div class="grid"><?php foreach($types as $t):?><div class="card"><h3><?=htmlspecialchars($t['service_type'])?></h3><div class="bar"><i style="width:<?=min(100,$t['c']*20)?>%"></i></div><p><?=$t['c']?> services</p></div><?php endforeach;?></div><div class="card table-wrap"><h2>Recent Usage Logs</h2><table><tr><th>Resource</th><th>Name</th><th>Usage %</th><th>Date</th></tr><?php foreach($logs as $l):?><tr><td><?=htmlspecialchars($l['resource_type'])?></td><td><?=htmlspecialchars($l['resource_name'])?></td><td><?=$l['usage_value']?>%</td><td><?=$l['usage_date']?></td></tr><?php endforeach;?></table></div></main><?php include 'includes/footer.php'; ?>